from taf.rfrl.procedures.resources.python.bts.components.bts_component import BtsComponent
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import Api


class Cell(BtsComponent):
    """ Represents generic Cell. """

    def __init__(self,
                 name: str,
                 api: Api,
                 api_alias: str):
        """
        :param name: name of this Cell, unique for BTS on which it is configured; i.e. 'NRCELL-1'
        :param api: API used for performing operations on this Cell
        :param api_alias: name of opened API connection which this Cell should use
        """
        super(Cell, self).__init__(name)
        self._rat = None
        self._technology = None
        self._api = api
        self._api_alias = api_alias

    def __eq__(self, other):
        return self._name == other.name

    @property
    def string_representation(self):
        return f'        {self._name} (RAT: {self._rat}, technology: {self._technology})'

    @property
    def rat(self) -> str:
        """ Returns Radio Access Technology in which this Cell is configured, i.e. 'NR', 'LTE'. """
        return self._rat

    @property
    def technology(self) -> str:
        """ Returns technology in which this Cell is configured, i.e. 'TDD', 'FDD'. """
        return self._technology

    def block(self, timeout: int):
        """
        Blocks this Cell by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.block.__name__))

    def unblock(self, timeout: int):
        """
        Unblocks this Cell by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.unblock.__name__))

    def lock(self, timeout: int):
        """
        Locks this Cell by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.lock.__name__))

    def unlock(self, timeout: int):
        """
        Unlocks this Cell by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.unlock.__name__))
